import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the solver parity golden-vector corpus against
/// `WeightedSquaredErrorScorer` and `CompositionSolver`'s earliest-wins
/// selection (issue #39).
///
/// The corpus is generated by the Elixir `color_matching` server
/// (`mix parity.generate`, committed upstream at `priv/parity/v1/corpus.json`)
/// and is the shared source of truth for client/server solver parity. Every
/// scenario records the palette response vectors, the target, the channel
/// weights, the per-candidate scores (or exclusions), the expected selection,
/// the winning error, and tie-break evidence. See
/// `docs/solver-parity-corpus.md` for where the corpus lives and how to
/// refresh it.
final class SolverParityCorpusTests: XCTestCase {
    private static var testDirectory: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent()
    }

    private static var corpusURL: URL {
        testDirectory.appendingPathComponent("Fixtures/parity/v1/corpus.json")
    }

    private var scorer: WeightedSquaredErrorScorer!

    override func setUp() {
        super.setUp()
        scorer = WeightedSquaredErrorScorer()
    }

    // MARK: - Corpus integrity

    /// The corpus must describe exactly the semantics the Swift scorer
    /// mirrors. A changed `algorithm_version`, scorer, selection policy, or
    /// missing-measurement policy means upstream solver semantics moved and
    /// every expectation in the corpus with them.
    func testCorpusMetadataMatchesMirroredSolverSemantics() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1, "algorithm_version moved: re-baseline deliberately per docs/solver-parity-corpus.md")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(Set(corpus.lightSources), Set(LightingCondition.allCases.map(\.rawValue)))
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12, "the v1 corpus carries 12 scenarios; fewer means the fixture is truncated")
    }

    // MARK: - Scorer parity

    /// Every per-candidate score in the corpus must be reproduced exactly —
    /// a finite Double for rankable candidates and an exclusion for anyone
    /// (candidate or target) missing a positive-weight channel.
    func testScorerScoresMatchCorpusExactly() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let palette = try makePalette(scenario)
            let target = makeTarget(scenario)
            let weights = makeWeights(scenario)

            for entry in scenario.expected.scores {
                let result = scorer.score(candidate: palette[entry.index], target: target, weights: weights)
                switch (result, entry.score) {
                case (.excluded, .excluded):
                    break
                case (.score(let value), .score(let expected)):
                    XCTAssertEqual(value, expected, accuracy: 1e-12, "\(scenario.id): candidate \(entry.index)")
                case (.score(let value), .excluded):
                    XCTFail("\(scenario.id): candidate \(entry.index) scored \(value) but the corpus expects it excluded")
                case (.excluded, .score(let expected)):
                    XCTFail("\(scenario.id): candidate \(entry.index) excluded but the corpus expects score \(expected)")
                }
            }
        }
    }

    /// Selection parity: the lowest score wins, ties break to the earliest
    /// palette index, and the winning hex color / error / tie evidence must
    /// all match. Scenarios where every candidate is excluded expect no
    /// selection at all.
    func testSelectionMatchesCorpusIncludingTies() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let palette = try makePalette(scenario)
            let target = makeTarget(scenario)
            let weights = makeWeights(scenario)

            let ranked: [(index: Int, score: Double)] = palette.indices.compactMap { index in
                guard case .score(let value) = scorer.score(candidate: palette[index], target: target, weights: weights) else {
                    return nil
                }
                return (index, value)
            }

            guard let minScore = ranked.map(\.score).min() else {
                XCTAssertNil(scenario.expected.selectedIndex, "\(scenario.id): expected no selection when every candidate is excluded")
                XCTAssertNil(scenario.expected.error, "\(scenario.id)")
                XCTAssertNil(scenario.expected.selectedHexColor, "\(scenario.id)")
                XCTAssertTrue(scenario.expected.tiedIndices.isEmpty, "\(scenario.id)")
                continue
            }

            let tied = ranked.filter { $0.score == minScore }.map(\.index).sorted()
            let selected = try XCTUnwrap(tied.first, "\(scenario.id): a selection must exist when any candidate is rankable")

            XCTAssertEqual(selected, scenario.expected.selectedIndex, "\(scenario.id): earliest index at the minimum score must win")
            XCTAssertEqual(tied, scenario.expected.tiedIndices, "\(scenario.id): every candidate at the minimum score is tied")
            XCTAssertEqual(scenario.expected.tieBroke, tied.count > 1, "\(scenario.id)")

            let expectedError = try XCTUnwrap(scenario.expected.error, "\(scenario.id): a selection implies an expected error")
            XCTAssertEqual(minScore, expectedError, accuracy: 1e-12, "\(scenario.id)")
            XCTAssertEqual(palette[selected].hex, scenario.expected.selectedHexColor, "\(scenario.id)")
        }
    }

    // MARK: - Solver parity

    /// The solver's optimized fast path must select the corpus-expected
    /// palette index — including exact ties (earliest wins) and
    /// all-excluded scenarios (cell left unmatched).
    ///
    /// Scenarios whose *target* is missing a positive-weight channel (the
    /// corpus's `missing-target-excluded`) cannot be expressed as
    /// `BrightnessGrid`s, which carry values rather than absences; that
    /// scenario's "every candidate excluded" outcome is already pinned by
    /// `testScorerScoresMatchCorpusExactly` and
    /// `testSelectionMatchesCorpusIncludingTies` above.
    func testSolverFastPathSelectionMatchesCorpus() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario)
            let active = weights.activeConditions
            let targetHasEveryActiveChannel = active.allSatisfy { scenario.target.channels[$0.rawValue] != nil }
            if !targetHasEveryActiveChannel { continue }

            let palette = try makePalette(scenario)
            var grids: [LightingCondition: BrightnessGrid] = [:]
            for condition in active {
                let value = try XCTUnwrap(scenario.target.channels[condition.rawValue], "\(scenario.id)")
                grids[condition] = BrightnessGrid(width: 1, height: 1, fill: value)
            }

            let result = try CompositionSolver().solve(palette: palette, sourceGrids: grids, weights: weights)

            if let selectedIndex = scenario.expected.selectedIndex {
                XCTAssertEqual(result.colorIndex(x: 0, y: 0), selectedIndex, "\(scenario.id): solver fast path must pick the corpus selection")
                let expectedError = try XCTUnwrap(scenario.expected.error, "\(scenario.id)")
                XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: 1e-12, "\(scenario.id)")
            } else {
                XCTAssertNil(result.colorIndex(x: 0, y: 0), "\(scenario.id): every candidate excluded must leave the cell unmatched")
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "\(scenario.id)")
                XCTAssertEqual(result.unmatchedCellCount, 1, "\(scenario.id)")
            }

            let expectedExcluded = scenario.expected.scores.filter { $0.score == .excluded }.count
            XCTAssertEqual(result.excludedCandidateCount, expectedExcluded, "\(scenario.id)")
        }
    }

    // MARK: - Corpus loading and conversion

    private func loadCorpus(file: StaticString = #filePath, line: UInt = #line) throws -> ParityCorpus {
        let url = Self.corpusURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            XCTFail("Parity corpus fixture is missing at \(url.path) — refresh it per docs/solver-parity-corpus.md", file: file, line: line)
            throw CocoaError(.fileNoSuchFile)
        }
        do {
            return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: url))
        } catch {
            XCTFail("Parity corpus fixture failed to decode: \(error)", file: file, line: line)
            throw error
        }
    }

    private func makePalette(_ scenario: ParityScenario) throws -> [PaletteColor] {
        try scenario.palette.map { try paletteColor(from: $0) }
    }

    private func makeTarget(_ scenario: ParityScenario) -> TargetResponseVector {
        targetVector(from: scenario.target)
    }

    private func makeWeights(_ scenario: ParityScenario) -> ChannelWeights {
        channelWeights(from: scenario.weights)
    }

    /// Unknown light-source keys (e.g. the `ultraviolet` weight in the
    /// `unknown-weight-ignored` scenario) are dropped, mirroring the server's
    /// `filter_weights/1` and the fixed canonical fields of `ChannelWeights`.
    private func channelWeights(from raw: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: raw["white"] ?? 0,
            red: raw["red"] ?? 0,
            green: raw["green"] ?? 0,
            blue: raw["blue"] ?? 0,
            lps: raw["lps"] ?? 0
        )
    }

    private func paletteColor(from vector: ParityVector) throws -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(
            id: vector.index ?? 0,
            hex: vector.hexColor,
            rgb: try XCTUnwrap(RGBColor(hex: vector.hexColor), "corpus hex \(vector.hexColor) must parse"),
            responses: responses
        )
    }

    private func targetVector(from vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }
}

// MARK: - Wire model of the corpus fixture

/// Shape of `priv/parity/v1/corpus.json` from `color_matching` (viamin/color_matching#111).
private struct ParityCorpus: Codable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case lightSources = "light_sources"
        case missingPolicy = "missing_policy"
        case scorer
        case selection
        case scenarios
    }
}

private struct ParityScenario: Codable {
    let id: String
    let description: String
    let palette: [ParityVector]
    let target: ParityVector
    /// Raw weights map; unknown light-source keys are ignored when converting.
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityVector: Codable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

private struct ParityExpectation: Codable {
    let error: Double?
    let scores: [ParityScoreEntry]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case error
        case scores
        case selectedHexColor = "selected_hex_color"
        case selectedIndex = "selected_index"
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

private struct ParityScoreEntry: Codable {
    let index: Int
    let score: ParityScore
}

/// A per-candidate expected outcome: a finite score or the `"excluded"` marker.
private enum ParityScore: Codable, Equatable {
    case score(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .score(value)
            return
        }
        let marker = try container.decode(String.self)
        guard marker == "excluded" else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Unknown score marker \"\(marker)\"; expected a number or \"excluded\""
            )
        }
        self = .excluded
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .score(let value): try container.encode(value)
        case .excluded: try container.encode("excluded")
        }
    }
}
